/** 🌲️ Round-5 Scots pine (Pinus sylvestris, about 100 years, open grown, 22 m): every stem section, root, stub, limb, branch, needle lobe and outlet is stated by hand per scale in world metres (x ahead, y up, z lateral) and written as bone-local solids to `volumes/vegetation/scots-pine.json`; the root fixes (lateral offsets of the pad bones, emitter anchors, limb-bark area, 2D drawings and plan symbol as true views of each scale's body) go to the candidate document `🗑️generated/r5-scots-pine/🔣️.json`.
 * @see ./round3-brief.md
 * @see ./r3-vegetation-scots-pine.md */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { GENERATED, SOURCES, entryOf, frames, toLocal, toWorld, type Frame, type Json, type V3 } from "./volumes-lib.ts";
import { D2R, add, along, branch, dirOf, dot3, len, mul, r4, r5, solidOf, sub, surfacePoint, unit, type Lobe, type Part, type Tube } from "./r3-scots-pine-kit.ts";
import { draw } from "./r3-scots-pine-draw.ts";

const { entry } = entryOf("vegetation/scots-pine");
const document: Json = JSON.parse(readFileSync(entry.path, "utf8"));
const asset: Json = document.asset;
const bone = (id: string): Json => asset.rig.bones.find((b: Json) => b.id === id);

type PadKey = "w3" | "e3" | "w1" | "e1" | "w2" | "e2" | "top" | "n" | "s";
type PadSpec = { bone: string; limb?: string; az: number; limbAz: number; z: number; shade: boolean };
export const PADS: Record<PadKey, PadSpec> = {
  w3: { bone: "pl-w3", limb: "limb-w3", az: 162, limbAz: 148, z: 1.64, shade: true },
  e3: { bone: "pl-e3", limb: "limb-e3", az: 344, limbAz: 328, z: -1.93, shade: true },
  w1: { bone: "pl-w1", limb: "limb-w1", az: 198, limbAz: 214, z: -1.89, shade: false },
  e1: { bone: "pl-e1", limb: "limb-e1", az: 16, limbAz: 32, z: 1.99, shade: false },
  w2: { bone: "pl-w2", limb: "limb-w2", az: 150, limbAz: 128, z: 1.7, shade: false },
  e2: { bone: "pl-e2", limb: "limb-e2", az: 330, limbAz: 310, z: -1.98, shade: false },
  top: { bone: "pl-top", az: 0, limbAz: 0, z: 0, shade: false },
  n: { bone: "trunk-3", az: 85, limbAz: 85, z: 0, shade: true },
  s: { bone: "trunk-3", az: 266, limbAz: 266, z: 0, shade: true },
};
const MAIN: PadKey[] = ["w3", "e3", "w1", "e1", "w2", "e2"];

for (const b of asset.rig.bones) delete b.z;
for (const key of MAIN) bone(PADS[key].bone).z = PADS[key].z;
const F: Record<string, Frame> = frames(asset);

const LOWER = "pine-bark-lower", UPPER = "pine-bark-upper", SUN = "pine-needles-sun", SHADE = "pine-needles-shade", WOOD = "pine-wood";
const TONE = { lower: 0.2, stub: 0.25, upper: 0.55, limb: 0.5, sun: 0.48, shade: 0.42 };

const JOINTS: [number, number][] = [[0, 0], [0, 7.4], [F["trunk-3"]!.o[0], F["trunk-3"]!.o[1]], [F.leader!.o[0], F.leader!.o[1]], [F["pl-top"]!.o[0], F["pl-top"]!.o[1]], [toWorld(F["pl-top"]!, [1.3, 0, 0])[0], toWorld(F["pl-top"]!, [1.3, 0, 0])[1]]];
/** 📏️ The x of the stem axis at the height `y` (the rig joints joined by straight lines). */
const axisX = (y: number): number => {
  for (let i = 0; i + 1 < JOINTS.length; i++) {
    const [a, b] = [JOINTS[i]!, JOINTS[i + 1]!];
    if (y <= b[1] || i + 2 === JOINTS.length) return a[0] + ((b[0] - a[0]) * (y - a[1])) / (b[1] - a[1]);
  }
  return 0;
};

type StemRow = [y: number, r: number, dx?: number, dz?: number];
/** 🌳️ A stem part on the stem axis: rows [height, radius with bark, x offset, z offset]. */
const stem = (id: string, boneId: string, material: string, tone: number, group: string, shape: string, rows: StemRow[]): Tube => ({ kind: "tube", id, bone: boneId, material, tone, group, shape, points: rows.map(([y, r, dx = 0, dz = 0]) => ({ p: [axisX(y) + dx, y, dz] as V3, r })) });

type LimbRow = [f: number, dy: number, dz: number, r: number];
/** 🪵️ A main limb from its joint on the stem axis to the origin of its pad bone: rows [fraction of the chord, sag (world up), lateral wobble, radius with bark]. */
function limb(key: PadKey, rows: LimbRow[]): Tube {
  const pad = PADS[key];
  const [b, t] = [F[pad.limb!]!.o, F[pad.bone]!.o];
  return { kind: "tube", id: pad.limb!, bone: pad.limb!, material: UPPER, tone: TONE.limb, group: "limb", shape: pad.limb!, points: rows.map(([f, dy, dz, r]) => ({ p: [b[0] + (t[0] - b[0]) * f, b[1] + (t[1] - b[1]) * f + dy, b[2] + (t[2] - b[2]) * f + dz] as V3, r })) };
}

/** 🥢️ A tube given in the local frame of its bone: rows [u, v, w, radius]. */
const local = (id: string, boneId: string, material: string, tone: number, group: string, shape: string, rows: [number, number, number, number][]): Tube => ({ kind: "tube", id, bone: boneId, material, tone, group, shape, points: rows.map(([u, v, w, r]) => ({ p: toWorld(F[boneId]!, [u, v, w]), r })) });

type SideRow = [name: string, f: number, dAz: number, e0: number, e1: number, L: number, r0: number, r1: number, bend: number];
type AxisRow = [e0: number, e1: number, L: number, r0: number, r1: number, bend: number];
type LobeRow = [size: "c" | "r" | "t", cluster: number, dr: number, dt: number, dy: number, a: number, b: number, c: number, yaw?: number, tilt?: number];

/** 🌿️ A needle lobe of a pad: centre at `dr` along the pad azimuth, `dt` across it and `dy` above the pad origin; semi-axes a (along), b (up), c (across), turned by `yaw` about the vertical and drooping outwards by `tilt`. */
function padLobe(key: PadKey, origin: V3, row: LobeRow, i: number, boneId?: string): Lobe {
  const pad = PADS[key];
  const [size, cluster, dr, dt, y0, a, b0, c, yaw = 0, tilt = 0] = row;
  const [dy, b] = key === "top" ? [y0 + b0 * 0.15, b0 * 0.85] : [y0 * 0.92, b0 * (size === "t" ? 0.8 : 0.92)];
  const R: V3 = [Math.cos(pad.az * D2R), 0, Math.sin(pad.az * D2R)], T: V3 = [-Math.sin(pad.az * D2R), 0, Math.cos(pad.az * D2R)];
  const turned = (pad.az + yaw) * D2R;
  const R1: V3 = [Math.cos(turned), 0, Math.sin(turned)], T1: V3 = [-Math.sin(turned), 0, Math.cos(turned)];
  const [ct, st] = [Math.cos(tilt * D2R), Math.sin(tilt * D2R)];
  const up: V3 = [0, 1, 0];
  return {
    kind: "lobe", id: `${key === "n" || key === "s" ? `pl-${key}` : pad.bone}-${size}${i + 1}`, bone: boneId ?? pad.bone, material: pad.shade ? SHADE : SUN, tone: pad.shade ? TONE.shade : TONE.sun + (key === "top" ? 0.06 : key === "w2" || key === "e2" ? 0.03 : 0),
    group: pad.shade ? "shade" : "sun", pad: key, cluster, size: size === "c" ? "core" : size === "r" ? "rim" : "tuft",
    c: add(add(add(origin, mul(R, dr)), mul(T, dt)), mul(up, dy)), axes: [sub(mul(R1, ct), mul(up, st)), add(mul(up, ct), mul(R1, st)), T1], radii: [a, b, c],
  };
}

