const padOrigin = (key: PadKey, wood: Tube[]): V3 => {
  if (key === "top") return F["pl-top"]!.o;
  if (key === "n" || key === "s") {
    const t = wood.find((x) => x.id === `limb-${key}`);
    return t ? t.points[t.points.length - 1]!.p : key === "n" ? [axisX(16.6) + 0.2, 16.62, 2.5] : [axisX(17.2) - 0.16, 17.2, -2.55];
  }
  return F[PADS[key].bone]!.o;
};

